function student(string $org='CCS',int $year=2):array{global $db,$period;$q=$db->prepare('SELECT id FROM organizations WHERE code=?');$q->execute([$org]);$orgId=(int)$q->fetchColumn();$email='qa.scenario.'.bin2hex(random_bytes(5)).'@thelewiscollege.edu.ph';$db->prepare("INSERT INTO users(email,password_hash,role,status)VALUES(?,?,'STUDENT','ACTIVE')")->execute([$email,password_hash('QA-only-2026!Test',PASSWORD_DEFAULT)]);$uid=(int)$db->lastInsertId();$db->prepare("INSERT INTO students(user_id,student_number,first_name,last_name,program,year_level,section,organization_id,status)VALUES(?,?,'QA','Scenario Student','BSCS',?,'QA-ONLY',?,'ACTIVE')")->execute([$uid,'QA-SC-'.bin2hex(random_bytes(4)),$year,$orgId]);$sid=(int)$db->lastInsertId();$db->prepare("INSERT INTO semester_enrollments(academic_period_id,student_id,status)VALUES(?,?,'ENROLLED')")->execute([$period,$sid]);prepareSemesterClearanceRecords($db,$period);$q=$db->prepare('SELECT id FROM clearances WHERE student_id=? AND academic_period_id=?');$q->execute([$sid,$period]);return ['id'=>$sid,'uid'=>$uid,'email'=>$email,'cid'=>(int)$q->fetchColumn(),'org'=>$orgId];}
function statuses(int $cid):array{global $db;$q=$db->prepare('SELECT s.code,cs.status FROM clearance_stations cs JOIN stations s ON s.id=cs.station_id WHERE cs.clearance_id=?');$q->execute([$cid]);return $q->fetchAll(PDO::FETCH_KEY_PAIR);}
function staff(string $role,?int $org=null):int{global $db,$fixture;if($org===null)return (int)$fixture['accounts'][$role]['id'];$q=$db->prepare("SELECT u.id FROM users u JOIN staff_assignments a ON a.user_id=u.id WHERE u.role=? AND a.organization_id=? AND a.status='ACTIVE' LIMIT 1");$q->execute([$role,$org]);return(int)$q->fetchColumn();}
function state(int $cid,string $code,string $status):void{global $db;$db->prepare('UPDATE clearance_stations cs JOIN stations s ON s.id=cs.station_id SET cs.status=? WHERE cs.clearance_id=? AND s.code=?')->execute([$status,$cid,$code]);}
function request(string $url,array &$account,array $post=[]):array{$ch=curl_init('http://127.0.0.1:8829'.$url);$opts=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>15];if(isset($account['cookie']))$opts[CURLOPT_COOKIE]=$account['cookie'];if($post!==[]){$opts[CURLOPT_POST]=true;$opts[CURLOPT_POSTFIELDS]=$post;}curl_setopt_array($ch,$opts);$raw=curl_exec($ch);if($raw===false)throw new RuntimeException(curl_error($ch));$size=curl_getinfo($ch,CURLINFO_HEADER_SIZE);$head=substr($raw,0,$size);if(preg_match('/Set-Cookie:\s*(clear_go_session=[^;\r\n]+)/i',$head,$m))$account['cookie']=$m[1];$r=['status'=>curl_getinfo($ch,CURLINFO_HTTP_CODE),'head'=>$head,'body'=>substr($raw,$size)];curl_close($ch);return$r;}
