result('Dean / Student','Signing not yet open','A PREPARING semester rejects clearance signing',statuses($early['cid'])['DEAN']!=='APPROVED',['period'=>'PREPARING','dean_status_after'=>statuses($early['cid'])['DEAN'],'exception'=>$error]);
